/**
 * Small, bounded syntax lexers for terminal diff presentation. Highlighting is
 * display-only: generated bytes never pass through or depend on this module.
 */
import { extname } from "node:path";
import { languageForCodeExtension } from "../core/languages.ts";

export type SyntaxStyle =
  | "keyword"
  | "type"
  | "function"
  | "string"
  | "number"
  | "comment"
  | "decorator"
  | "builtin"
  | "property"
  | "tag";

export interface SyntaxSpan {
  start: number;
  end: number;
  style: SyntaxStyle;
}

